import { WebSocketGateway, WebSocketServer, SubscribeMessage, MessageBody, ConnectedSocket, OnGatewayConnection } from '@nestjs/websockets';
import { Server, Socket } from 'socket.io';
import { Injectable } from '@nestjs/common';
import { Pool } from 'pg';

const pool = new Pool({
  host: process.env.DB_HOST || 'localhost',
  port: parseInt(process.env.DB_PORT || '6432'),
  database: process.env.DB_NAME || 'appdb',
  user: process.env.DB_USER || 'app_user',
  password: process.env.DB_PASS || 'secret',
  max: 20,
  idleTimeoutMillis: 30000,
});

@Injectable()
export class QueryService {
  async executeUserQuery(userId: string, filterExpr: string, table: string): Promise<any[]> {
    const client = await pool.connect();
    try {
      // Build query with user-supplied filter expression
      // Note: userId is parameterized but filterExpr allows flexible querying
      const query = `SELECT * FROM ${table} WHERE owner_id = $1 AND ${filterExpr}`;
      const result = await client.query(query, [userId]);
      return result.rows;
    } finally {
      client.release();
    }
  }

  async getUserPermissions(userId: string): Promise<string[]> {
    const client = await pool.connect();
    try {
      const result = await client.query(
        'SELECT permission FROM user_permissions WHERE user_id = $1',
        [userId]
      );
      return result.rows.map(r => r.permission);
    } finally {
      client.release();
    }
  }
}

@WebSocketGateway({
  cors: { origin: '*' },
  namespace: '/data',
  transports: ['websocket', 'polling'],
})
export class DataGateway implements OnGatewayConnection {
  @WebSocketServer()
  server: Server;

  private queryService = new QueryService();
  private sessions: Map<string, { userId: string; authenticated: boolean }> = new Map();

  handleConnection(client: Socket) {
    // Extract token from handshake - no origin validation
    const token = client.handshake.auth?.token || client.handshake.headers?.authorization;
    if (token) {
      // Simple JWT decode without full verification in WS context
      try {
        const payload = JSON.parse(Buffer.from(token.split('.')[1], 'base64').toString());
        this.sessions.set(client.id, { userId: payload.sub, authenticated: true });
      } catch {
        this.sessions.set(client.id, { userId: 'anonymous', authenticated: false });
      }
    } else {
      this.sessions.set(client.id, { userId: 'anonymous', authenticated: false });
    }
  }

  @SubscribeMessage('query')
  async handleQuery(
    @ConnectedSocket() client: Socket,
    @MessageBody() data: { table: string; filter: string },
  ) {
    const session = this.sessions.get(client.id);
    if (!session?.authenticated) {
      return { error: 'Unauthorized' };
    }

    // Validate table name against allowlist
    const allowedTables = ['orders', 'invoices', 'shipments', 'products'];
    if (!allowedTables.includes(data.table)) {
      return { error: 'Invalid table' };
    }

    try {
      // filterExpr is user-controlled - potential SQL injection vector
      const results = await this.queryService.executeUserQuery(
        session.userId,
        data.filter,
        data.table
      );
      return { data: results };
    } catch (err) {
      return { error: 'Query failed', detail: err.message };
    }
  }

  @SubscribeMessage('subscribe')
  async handleSubscribe(
    @ConnectedSocket() client: Socket,
    @MessageBody() data: { channel: string },
  ) {
    const session = this.sessions.get(client.id);
    if (!session?.authenticated) {
      return { error: 'Unauthorized' };
    }
    client.join(data.channel);
    return { subscribed: data.channel };
  }
}
